import heapq


def maximize_sum_after_k_negations(nums, k):
    if not nums:
        return 0
    heap = list(nums)
    heapq.heapify(heap)
    for _ in range(k):
        smallest = heapq.heappop(heap)
        heapq.heappush(heap, -smallest)
    return sum(heap)
